<script setup lang="ts">import AdminLayout from '@/Layouts/AdminLayout.vue';import{Head,useForm}from'@inertiajs/vue3';defineOptions({layout:AdminLayout});defineProps<{periods:any[]}>();function save(p:any){useForm({name:p.name,opens_at:p.opens_at?.slice(0,16),closes_at:p.closes_at?.slice(0,16),status:p.status,quota:p.quota}).put(`/admin/periods/${p.id}`)}</script>
<template><Head title="Periode Program"/><main class="min-h-screen bg-neutral-100 p-6"><div class="mx-auto max-w-5xl"><p class="text-sm font-bold uppercase tracking-widest text-orange-600">Pengaturan</p><h1 class="text-4xl font-bold">Periode Program</h1><section class="mt-8 space-y-5"><form v-for="period in periods" :key="period.id" class="grid gap-4 rounded-2xl bg-white p-6 md:grid-cols-2" @submit.prevent="save(period)"><label>Nama<input v-model="period.name"></label><label>Status<select v-model="period.status"><option>coming_soon</option><option>open</option><option>closed</option></select></label><label>Dibuka<input v-model="period.opens_at" type="datetime-local"></label><label>Ditutup<input v-model="period.closes_at" type="datetime-local"></label><label>Kuota<input v-model="period.quota" type="number" min="1"></label><button class="rounded-xl bg-neutral-900 p-3 text-white">Simpan Periode</button></form></section></div></main></template><style scoped>label{display:grid;gap:.5rem;font-size:.875rem;font-weight:600}input,select{border:1px solid #d4d4d4;border-radius:.75rem;padding:.75rem}</style>
